package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceAttendanceMonthController;import com.rpb.reservation.workforce.attendance.daily.*;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(WorkforceAttendanceMonthController.class) @Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class}) @ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforceAttendanceMonthLocalRuntimeSecurityTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean AttendanceDailyService daily;@MockBean AttendanceExceptionService exceptions;@MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 @Test void onlyExactMonthAndExceptionMethodsReachServices()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce";UUID id=UUID.randomUUID();mvc.perform(get(base+"/attendance-month").param("month","2026-11")).andExpect(status().isOk());mvc.perform(get(base+"/attendance-exceptions").param("from","2026-11-01").param("to","2026-11-30")).andExpect(status().isOk());for(var path:List.of("/attendance-days/"+id+"/review","/attendance-month/refresh","/attendance-exceptions/"+id,"/attendance-exceptions/"+id+"/decision"))mvc.perform(put(base+path).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());verify(daily).month(any(),any(),any(),isNull(),isNull(),isNull(),eq(30),eq(0));verify(daily).refresh(any(),any(),any());verify(exceptions).list(any(),any(),any(),any(),isNull());verify(exceptions).submit(any(),any(),eq(id),any());verify(exceptions).decide(any(),any(),eq(id),any());mvc.perform(delete(base+"/attendance-exceptions/"+id)).andExpect(status().isForbidden());mvc.perform(post(base+"/attendance-month/refresh")).andExpect(status().isForbidden());mvc.perform(put(base+"/attendance-month/unsupported").contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put(base+"/attendance-exceptions/"+id+"/approve").contentType("application/json").content("{}")).andExpect(status().isForbidden());}
}
